  function note(parent,title,detail){rule(parent,342,'ink',2);label(parent,title);text(parent,detail,'small','ink',342,.8);}
  function field(parent,name,value,state='Default'){label(parent,name);const n=instance(parent,fields[state]);n.findOne(x=>x.type==='TEXT').characters=value;return n;}
  function nav(parent,active){const f=box(parent,'Bottom navigation',390,0,24,true);f.paddingTop=f.paddingBottom=4;rule(parent,390);f.resize(390,66);f.primaryAxisSizingMode='FIXED';[['Apps','Grid2X2','home'],['Activity','Activity','activity'],['Settings','Settings','settings']].forEach(([title,ic,target])=>{const i=instance(f,navComp[title===active?'Active':'Rest']);i.findOne(n=>n.type==='TEXT').characters=title;links.push([i,target]);});return f;}
  function screen(key,name,kicker,title,subtitle='',active){const i=Object.keys(screens).length;const root=box(screenPage,name,390);root.resize(390,844);root.primaryAxisSizingMode='FIXED';root.fills=[paint('paper')];root.clipsContent=true;root.x=80+(i%6)*454;root.y=140+Math.floor(i/6)*970;screens[key]=root;const status=box(root,'Android status bar',390,0,24,true);status.paddingTop=status.paddingBottom=8;status.primaryAxisAlignItems='SPACE_BETWEEN';text(status,'9:41','small','ink',100);const statusRight=text(status,'5G  ·  100%','small','ink',125);statusRight.textAlignHorizontal='RIGHT';instance(root,header);rule(root,390,'ink');const body=box(root,'Content',390,8,24);body.layoutGrow=1;body.primaryAxisSizingMode='FIXED';if(kicker)label(body,kicker);if(title)text(body,title,'display');if(subtitle)text(body,subtitle,'body','ink',342,.78);if(active)nav(root,active);else{const footer=box(root,'Footer',390,0,24,true);footer.paddingTop=footer.paddingBottom=12;footer.primaryAxisAlignItems='SPACE_BETWEEN';text(footer,'GHOSTNET AUTH','label','ink',160,.65);text(footer,'ANDROID','label','ink',100,.65);}return body;}
  function section(parent,title,count){const b=box(parent,'Section header',342,0,0,true);b.primaryAxisAlignItems='SPACE_BETWEEN';text(b,title,'label','ink',270,.75);text(b,count,'label','ink',40);rule(parent,342,'ink',2);}
  function pin(parent,filled=0){const p=box(parent,'PIN entry / six digits',342,12,0,true);p.primaryAxisAlignItems='CENTER';for(let i=0;i<6;i++){const d=box(p,'Digit '+(i+1),40);d.resize(40,50);d.primaryAxisSizingMode='FIXED';d.counterAxisAlignItems='CENTER';d.primaryAxisAlignItems='CENTER';d.strokes=[paint(i===filled?'cobalt':'stone')];const t=text(d,i<filled?'•':'','heading','ink',30);t.textAlignHorizontal='CENTER';}return p;}
  function keypad(parent,target){const grid=box(parent,'Numeric keypad',342,8);[['1','2','3'],['4','5','6'],['7','8','9'],['','0','⌫']].forEach(values=>{const r=box(grid,'Keypad row',342,12,0,true);values.forEach(value=>{const k=box(r,'Key '+value,106);k.resize(106,48);k.primaryAxisSizingMode='FIXED';k.primaryAxisAlignItems='CENTER';const t=text(k,value,'heading','ink',106);t.textAlignHorizontal='CENTER';if(value&&target)links.push([k,target]);});});}
  let b=screen('welcome','01 / Welcome','PRIVATE BY DESIGN','Your apps.\nYour access.','Adaptive protection for the things you keep on your phone.');logo(b,190);spacer(b);button(b,'Set up GhostNet','privacy');text(b,'A few steps. Always in your control.','small','ink',342,.7);
