  b=screen('home','09 / App protection','YOUR DEVICE / YOUR RULES','App\nprotection.','', 'Apps');const st=box(b,'Protection status',342,8,0,true);icon(st,'Check',18,'cobalt');text(st,'Protection is active','small','ink',280);section(b,'SELECTED APPS','03');row(b,'Mail','Messages & accounts','On','appDetail');row(b,'Photos','Personal library','On','appDetail');row(b,'Files','Documents & downloads','On','appDetail');spacer(b);button(b,'Choose apps','manageApps');
