  b=screen('manageApps','11 / Manage applications','APP SELECTION','Choose apps.');const searchField=instance(b,fields.Default);searchField.findOne(n=>n.type==='TEXT').characters='Search installed apps';searchField.resize(342,44);row(b,'Mail','Messages & accounts','On');row(b,'Photos','Personal library','On');row(b,'Files','Documents & downloads','On');row(b,'Browser','Browsing & saved logins','Off');spacer(b);button(b,'Save selection','home');
  b=screen('appDetail','12 / App protection details','PROTECTED APPLICATION','Mail.','Messages & accounts');item(b,'Protection','On · adaptive verification');item(b,'Current session','Additional verification required','risk');item(b,'Recent activity','Review access attempts','activity');note(b,'How access works','Low-risk sessions continue. Higher-risk sessions need verification or remain restricted.');spacer(b);button(b,'Preview identity check','pinVerify');button(b,'Back to apps','home','Secondary');
  b=screen('risk','13 / Session details','SESSION CONTEXT','Why this\ncheck?','This session differs from your usual pattern.');item(b,'Network changed','You recently joined another network.');item(b,'Behavior profile','Still learning your normal interactions.');item(b,'Device checks','Available checks passed.');note(b,'Additional verification','Confirm your identity before continuing to Mail.');spacer(b);button(b,'Verify identity','pinVerify');button(b,'Back','appDetail','Secondary');
