  const swatches=box(guide,'Exact palette',880,16,0,true);Object.entries(hex).forEach(([name,h])=>{const s=box(swatches,name,208,8);const chip=rule(s,208,name,90);text(s,name.toUpperCase(),'label','ink',208);text(s,h,'row','ink',208);});
  text(guide,'Typography','heading','ink',880);text(guide,'Arial Regular / Bold · Courier New for utility labels','body','ink',880);text(guide,'Display 46/48 · Heading 32/36 · Body 15/22 · Labels 11/16','small','ink',880);text(guide,'Layout','heading','ink',880);text(guide,'390 × 844 Android frames · 24 px content margins · 4 px spacing scale\n52 px primary actions · minimum 48 px touch targets · 3 px control corners','body','ink',880);
  text(guide,'Meaning and accessibility','heading','ink',880);text(guide,'Cobalt marks actions and verified identity. It is not a universal safe-state indicator. Risk is communicated through explicit language and icons. No extra red or green is introduced into the approved palette.','body','ink',880);text(guide,'Prototype scope','heading','ink',880);text(guide,'24 editable screens with linked setup, protection and verification journeys. Android permission and biometric screens are represented as handoff destinations, not real operating-system dialogs. No biometric data, credentials or app content is processed by this prototype.','body','ink',880);text(guide,'Research and implementation decisions','heading','ink',880);text(guide,'High-risk access remains restricted. Consumer Android app enforcement, behavior-signal availability, recovery enrollment and measured risk thresholds require technical validation. The approved logo remains the original raster asset; interface text, layouts and icons are editable Figma layers.','body','ink',880);
  const allScreens=Object.values(screens);
  const audit={screens:allScreens.length,components:componentPage.findAll(n=>n.type==='COMPONENT').length,instances:screenPage.findAll(n=>n.type==='INSTANCE').length,text:screenPage.findAll(n=>n.type==='TEXT').length,links:links.length,fonts:[...new Set(screenPage.findAll(n=>n.type==='TEXT').map(n=>n.fontName.family))],screenIds:Object.fromEntries(Object.entries(screens).map(([k,n])=>[k,n.id])),createdIds:allCreated,overflow:[]};
  for(const screen of allScreens){for(const n of screen.findAll(n=>n.type==='TEXT')){const bb=n.absoluteBoundingBox, sb=screen.absoluteBoundingBox;if(bb&&(bb.x<sb.x-.5||bb.y<sb.y-.5||bb.x+bb.width>sb.x+sb.width+.5||bb.y+bb.height>sb.y+sb.height+.5))audit.overflow.push(screen.name+' / '+n.characters);}}
